mod pencil;mod linear;mod phase;
#[path="../native-prepared-solvers/dense.rs"]mod dense;
#[path="../native-prepared-solvers/prepared.rs"]mod prepared;
#[path="../native-prepared-solvers/table_oracle.rs"]mod table_oracle;
#[path="../native-prepared-solvers/tail.rs"]mod tail;
#[path="../native-prepared-solvers/walk.rs"]mod walk;
use hec_native_ic::{counted,instance::pick_instance,rng::Rng};
fn key<'a>(line:&'a str,k:&str)->Option<&'a str>{line.split_whitespace().find_map(|s|s.strip_prefix(&format!("{k}=")))}
fn main(){let old=include_str!("../native-prepared-solvers/CONTROL.txt");let mut calls=0;
for line in include_str!("../native-pencil-3lp/INSTANCES.tsv").lines().skip(1){counted::disable();let v:Vec<_>=line.split('\t').collect();let g:usize=v[0].parse().unwrap();let p:u64=v[1].parse().unwrap();let cc:u64=v[2].parse().unwrap();let ell:u64=v[3].parse().unwrap();let inst=pick_instance(p,g).unwrap();assert_eq!(inst.c,cc);assert_eq!(inst.ell,ell);assert_eq!(inst.curve.f.c[..inst.curve.f.n].iter().map(u64::to_string).collect::<Vec<_>>().join(","),v[4]);let mut rng=Rng::new(2026111800^p^((g as u64)<<32));
for case in 0..2{let sm=if case==0{1}else{17};let d=inst.curve.mul(&inst.d1,sm);let k=1+rng.below(ell-1);let t=inst.curve.mul(&d,k);let matches=|l:&str|key(l,"g")==Some(v[0])&&key(l,"p")==Some(v[1])&&key(l,"source_multiple").or(key(l,"sm"))==Some(sm.to_string().as_str())&&key(l,"case")==Some(case.to_string().as_str())&&key(l,"arm")==Some("pencil_tail")&&key(l,"rep")==Some("0");let mut prior=None;
for rep in 0..2{eprintln!("start g={g} p={p} sm={sm} rep={rep}");counted::reset();phase::reset();phase::set("validate");walk::validate(&inst.curve,&d,&t,ell);phase::set("prepare");let prep=prepared::prepare(&inst.curve,false);phase::set("collector_init");let r=pencil::solve(&inst.curve,&d,&t,ell,512,false,&prep);let phases=phase::finish();let total=counted::snapshot();counted::disable();assert_eq!(r.k,Some(k));assert_eq!(inst.curve.mul(&d,k),t);let signature=format!("{r:?}");let oldout=old.lines().find(|l|l.starts_with("OUTCOME ")&&matches(l)).unwrap();assert_eq!(oldout.split("report=").nth(1).unwrap(),signature);let lookups=(prep.roots.sqrt_lookups.get(),prep.roots.legendre_lookups.get(),prep.roots.bytes());assert_eq!(key(oldout,"sqrt_lookups").unwrap().parse::<u64>().unwrap(),lookups.0);assert_eq!(key(oldout,"legendre_lookups").unwrap().parse::<u64>().unwrap(),lookups.1);
let mut sum=counted::Counts::new();for values in phases.values(){for(&modulus,v)in values{let s=sum.entry(modulus).or_insert([0;16]);for j in 0..16{s[j]+=v[j];}}}assert_eq!(sum,total);for(&modulus,values)in &total{let prior=old.lines().find(|l|l.starts_with("COUNT ")&&matches(l)&&key(l,"modulus")==Some(modulus.to_string().as_str())).unwrap();let vv:Vec<u64>=prior.split("vector=[").nth(1).unwrap().trim_end_matches(']').split(',').map(|s|s.trim().parse().unwrap()).collect();assert_eq!(values.as_slice(),vv.as_slice());println!("TOTAL g={g} p={p} sm={sm} case={case} rep={rep} modulus={modulus} vector={values:?}");}let state=(signature.clone(),total,phases.clone(),lookups);if let Some(old)=&prior{assert_eq!(old,&state);}else{prior=Some(state);}for(label,values)in phases{for(modulus,vector)in values{println!("PHASE g={g} p={p} sm={sm} case={case} rep={rep} phase={label} modulus={modulus} vector={vector:?}");}}println!("OUTCOME g={g} p={p} sm={sm} case={case} rep={rep} report={signature}");calls+=1;
}}}assert_eq!(calls,44);eprintln!("PASS calls={calls} original_totals_replay=true phases_partition_every_counter=true repeated_phases_exact=true native_verified=true no_wall_or_tenfold_claim=true");}
